def transform(grid):
    out=[row[:] for row in grid]
    anchors=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
    if len(anchors)!=2: return out
    # identify the anchor adjacent to the colored pattern
    def near(a):
        r,c=a
        return sum(grid[rr][cc]!=0 and grid[rr][cc]!=5 for rr in range(max(0,r-2),min(len(grid),r+3)) for cc in range(max(0,c-2),min(len(grid[0]),c+3)))
    src=max(anchors,key=near); dst=anchors[1] if anchors[0]==src else anchors[0]
    dr,dc=dst[0]-src[0],dst[1]-src[1]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v=grid[r][c]
            if v and v!=5:
                rr,cc=r+dr,c+dc
                if 0<=rr<len(grid) and 0<=cc<len(grid[0]) and (rr,cc)!=dst: out[rr][cc]=v
    return out
